-- 123: Original BrillaPrep WASSCE Commerce Detailed Syllabus beta questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_031', 'topic_was_commerce_7', 'subj_wassce_commerce', 'exam_wassce', 'What is market segmentation?', 'multiple_choice', '["A. Charging every customer a random price","B. Producing without studying demand","C. Dividing customers into groups with relevant shared characteristics","D. Eliminating all product differences"]', 'C', 'Segmentation helps a business tailor products, messages and channels to groups with similar needs, behaviour or purchasing power. Therefore the correct answer is C: Dividing customers into groups with relevant shared characteristics.', 'easy', 1, 1, 90, 'st_was_commerce_7', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_032', 'topic_was_commerce_7', 'subj_wassce_commerce', 'exam_wassce', 'Which element of the marketing mix concerns how a product reaches the customer?', 'multiple_choice', '["A. Product","B. Price","C. Promotion","D. Place"]', 'D', 'Place covers distribution channels, location, logistics and availability, while the other elements address the offer, charge and communication. Therefore the correct answer is D: Place.', 'medium', 2, 2, 90, 'st_was_commerce_7', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_033', 'topic_was_commerce_7', 'subj_wassce_commerce', 'exam_wassce', 'Why should an advertisement avoid false performance claims?', 'multiple_choice', '["A. They can mislead consumers and breach fair-trading obligations","B. False claims always improve long-term trust","C. Advertising is exempt from every law","D. Consumers never rely on product information"]', 'A', 'Accurate claims support informed choice and sustainable trust, while deceptive claims can trigger complaints, sanctions and reputational damage. Therefore the correct answer is A: They can mislead consumers and breach fair-trading obligations.', 'hard', 1, 1, 90, 'st_was_commerce_7', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_034', 'topic_was_commerce_7', 'subj_wassce_commerce', 'exam_wassce', 'What is branding intended to do?', 'multiple_choice', '["A. Guarantee that the product is cheapest","B. Create a recognisable identity that distinguishes an offering","C. Remove the need for consistent quality","D. Prevent competitors from advertising"]', 'B', 'Names, symbols and associations help buyers recognise and evaluate an offering, but the brand promise must be supported by actual experience. Therefore the correct answer is B: Create a recognisable identity that distinguishes an offering.', 'easy', 2, 2, 90, 'st_was_commerce_7', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_035', 'topic_was_commerce_7', 'subj_wassce_commerce', 'exam_wassce', 'Which evidence is most useful before launching a new retail product?', 'multiple_choice', '["A. The owner’s preference alone","B. A supplier’s colour choice only","C. Research on customer needs, competitors, price and likely demand","D. An unrelated company’s payroll"]', 'C', 'Market research reduces avoidable uncertainty by testing the target need, purchasing conditions, alternatives and commercial viability. Therefore the correct answer is C: Research on customer needs, competitors, price and likely demand.', 'medium', 3, 3, 90, 'st_was_commerce_7', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_036', 'topic_was_commerce_8', 'subj_wassce_commerce', 'exam_wassce', 'What is a major benefit of e-commerce to a small retailer?', 'multiple_choice', '["A. Every online visitor must buy","B. Delivery and fraud risks disappear","C. Internet access becomes unnecessary","D. Customers can view and order products beyond the physical shop’s opening hours"]', 'D', 'An online channel can widen reach and availability, but the retailer must still manage payments, fulfilment, security and customer service. Therefore the correct answer is D: Customers can view and order products beyond the physical shop’s opening hours.', 'hard', 2, 2, 90, 'st_was_commerce_8', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_037', 'topic_was_commerce_8', 'subj_wassce_commerce', 'exam_wassce', 'Which control most directly protects an online customer account?', 'multiple_choice', '["A. Strong authentication and secure handling of credentials","B. Publishing passwords for convenience","C. Disabling transaction records","D. Accepting every login attempt without limits"]', 'A', 'Authentication, protected credential storage and monitoring reduce account takeover risk and support trustworthy digital commerce. Therefore the correct answer is A: Strong authentication and secure handling of credentials.', 'easy', 1, 1, 90, 'st_was_commerce_8', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_038', 'topic_was_commerce_8', 'subj_wassce_commerce', 'exam_wassce', 'How can inflation affect a trading business?', 'multiple_choice', '["A. It guarantees that real profit rises","B. It can raise input costs and reduce customers’ purchasing power","C. It prevents prices from changing","D. It removes the need for working capital"]', 'B', 'Persistent price increases change costs, selling prices, cash needs and real consumer incomes, requiring budgets and pricing decisions to be reviewed. Therefore the correct answer is B: It can raise input costs and reduce customers’ purchasing power.', 'medium', 2, 2, 90, 'st_was_commerce_8', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_039', 'topic_was_commerce_8', 'subj_wassce_commerce', 'exam_wassce', 'Which is a technological factor in the business environment?', 'multiple_choice', '["A. The age distribution of the population","B. A new consumer-protection statute","C. Adoption of mobile payments and digital inventory systems","D. Changes in rainfall affecting farms"]', 'C', 'Technology changes how firms produce, sell, communicate and control information, creating both efficiency opportunities and new operational risks. Therefore the correct answer is C: Adoption of mobile payments and digital inventory systems.', 'hard', 1, 1, 90, 'st_was_commerce_8', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_commerce_b001_040', 'topic_was_commerce_8', 'subj_wassce_commerce', 'exam_wassce', 'Why should a business keep accurate transaction records?', 'multiple_choice', '["A. Records make internal controls unnecessary","B. Records guarantee that theft cannot occur","C. Only failed businesses need records","D. They support decisions, tax compliance, reconciliation and accountability"]', 'D', 'Reliable records show what was sold, received and owed, enabling management review, statutory reporting and investigation of discrepancies. Therefore the correct answer is D: They support decisions, tax compliance, reconciliation and accountability.', 'easy', 3, 3, 90, 'st_was_commerce_8', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published WAEC Ghana Commerce syllabus; not official WAEC examination material.', 'https://waecgh.org/wp-content/uploads/2024/07/COMMERCE.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_commerce_b001_031' AND 'q_was_commerce_b001_040';
